【一个简单的echarts-demo的实现】github pages 加载会有点慢,demo就不去cdn优化了



        // 基于准备好的dom，初始化echarts实例
        var myChart = echarts.init(document.getElementById('echarts6026'));
        // 指定图表的配置项和数据
        var option = {
	 tooltip : {
        trigger: 'axis',
        axisPointer : {            // 坐标轴指示器，坐标轴触发有效
            type : 'shadow'        // 默认为直线，可选为：'line' | 'shadow'
        }
    },
    legend: {
        data:['利润', '支出', '收入']
    },
    grid: {
        left: '3%',
        right: '4%',
        bottom: '3%',
        containLabel: true
    },
    xAxis : [
        {
            type : 'value'
        }
    ],
    yAxis : [
        {
            type : 'category',
            axisTick : {show: false},
            data : ['周一','周二','周三','周四','周五','周六','周日']
        }
    ],
    series : [
        {
            name:'利润',
            type:'bar',
            label: {
                normal: {
                    show: true,
                    position: 'inside'
                }
            },
            data:[200, 170, 240, 244, 200, 220, 210]
        },
        {
            name:'收入',
            type:'bar',
            stack: '总量',
            label: {
                normal: {
                    show: true
                }
            },
            data:[320, 302, 341, 374, 390, 450, 420]
        },
        {
            name:'支出',
            type:'bar',
            stack: '总量',
            label: {
                normal: {
                    show: true,
                    position: 'left'
                }
            },
            data:[-120, -132, -101, -134, -190, -230, -210]
        }
    ]
}
        // 使用刚指定的配置项和数据显示图表。
        myChart.setOption(option);

此图表是echarts的demo【google chrome浏览器会把echarts的脚本识别为不安全脚本，点击url栏最后的拦截脚本的安全盾，然后加载不安全脚本就可以看到效果图】下面是echarts中的力导图的html实现 

为ECharts准备一个具备大小（宽高）的Dom&lt;div id=&quot;main&quot; style=&quot;width: 600px;height:400px;&quot;&gt;&lt;/div&gt;


引入jquery&lt;script type=&quot;text/javascript&quot; src=&quot;http://ajax.microsoft.com/ajax/jquery/jquery-1.4.min.js&quot;&gt;&lt;/script&gt;


引入echarts.js&lt;script src=&quot;js/echarts.js&quot;&gt;&lt;/script&gt;&lt;!-- echarts 新版本不支持force图，只能导入这个本地的（旧版）包--&gt;




在script标签中编写具体代码对require.config进行编写引入js文件夹，并命名为 echarts
require.config(&#123;			paths: &#123;				echarts: &#x27;js&#x27;			&#125;		&#125;);

对require进行编写导入其他有用的模块（都在js文件夹下)require(			[				&#x27;echarts&#x27;,				&#x27;echarts/chart/bar&#x27;,				&#x27;echarts/chart/line&#x27;,				&#x27;echarts/chart/map&#x27;,				&#x27;echarts/chart/force&#x27;,				&#x27;echarts/chart/chord&#x27;			],			......//这里省略的代码在下面步骤		)

编辑图表代码（附上全部代码，具体修改见fuction）&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt;    &lt;meta charset=&quot;utf-8&quot;&gt;    &lt;title&gt;ECharts&lt;/title&gt;&lt;/head&gt;&lt;body&gt;	&lt;P&gt;SDGYASDGSAJD ASDAS &lt;/P&gt;    &lt;!-- 1 为ECharts准备一个具备大小（宽高）的Dom --&gt;    &lt;div id=&quot;main&quot; style=&quot;width: 600px;height:400px;&quot;&gt;&lt;/div&gt;    &lt;!-- 2 引入jquery（要在echarts.js前面 --&gt;    &lt;script type=&quot;text/javascript&quot; src=&quot;http://ajax.microsoft.com/ajax/jquery/jquery-1.4.min.js&quot;&gt;&lt;/script&gt;    &lt;!-- 3 引入echarts.js--&gt;	&lt;script src=&quot;js/echarts.js&quot;&gt;&lt;/script&gt;&lt;!-- echarts 新版本不支持force图，只能导入这个本地的（旧版）包--&gt;    &lt;!--&lt;script type=&quot;text/javascript&quot; src=&quot;http://echarts.baidu.com/gallery/vendors/echarts/echarts.min.js&quot;&gt;&lt;/script&gt;--&gt;		&lt;!-- step4 编写js--&gt;	&lt;!--在这里引入主题文件--&gt;	&lt;script type=&quot;text/javascript&quot;&gt;		&lt;!-- step4-1 引入js文件夹，并命名为 echarts--&gt;		require.config(&#123;			paths: &#123;				echarts: &#x27;js&#x27;			&#125;		&#125;);		&lt;!-- step4-2 将代码写在require里面--&gt;		require(			&lt;!-- step4-2-1 导入其他有用的模块（都在js文件夹下）--&gt;			[				&#x27;echarts&#x27;,				&#x27;echarts/chart/bar&#x27;,				&#x27;echarts/chart/line&#x27;,				&#x27;echarts/chart/map&#x27;,				&#x27;echarts/chart/force&#x27;,				&#x27;echarts/chart/chord&#x27;			],			&lt;!-- step4-2-2 编辑图表代码--&gt;			function (ec) &#123;				&lt;!--step4-2-2-1 设置数据--&gt;				var option=&#123;								//------------------------------------------								//此处以下是在官网上调试好的数据代码								title : &#123;									text: &#x27;标题&#x27;,									subtext: &#x27;副标题&#x27;,									x:&#x27;right&#x27;,									y:&#x27;bottom&#x27;								&#125;,								tooltip : &#123;									trigger: &#x27;item&#x27;,									formatter: &#x27;&#123;a&#125; : &#123;b&#125;&#x27;								&#125;,								toolbox: &#123;									show : true,									feature : &#123;										restore : &#123;show: true&#125;,										magicType: &#123;show: true, type: [&#x27;force&#x27;, &#x27;chord&#x27;]&#125;,										saveAsImage : &#123;show: true&#125;									&#125;								&#125;,								legend: &#123;									x: &#x27;left&#x27;,									data:[&#x27;家人&#x27;,&#x27;朋友&#x27;]								&#125;,								series : [									&#123;										type:&#x27;force&#x27;,										name : &quot;人物关系&quot;,										ribbonType: false,										categories : [											&#123;												name: &#x27;人物&#x27;											&#125;,											&#123;												name: &#x27;家人&#x27;											&#125;,											&#123;												name:&#x27;朋友&#x27;											&#125;										],										itemStyle: &#123;											normal: &#123;												label: &#123;													show: true,													textStyle: &#123;														color: &#x27;#333&#x27;													&#125;												&#125;,												nodeStyle : &#123;													brushType : &#x27;both&#x27;,													borderColor : &#x27;rgba(255,215,0,0.4)&#x27;,													borderWidth : 1												&#125;,												linkStyle: &#123;													type: &#x27;curve&#x27;												&#125;											&#125;,											emphasis: &#123;												label: &#123;													show: false													// textStyle: null      // 默认使用全局文本样式，详见TEXTSTYLE												&#125;,												nodeStyle : &#123;													//r: 30												&#125;,												linkStyle : &#123;&#125;											&#125;										&#125;,										useWorker: false,										minRadius : 15,										maxRadius : 25,										gravity: 1.1,										scaling: 1.1,										roam: &#x27;move&#x27;,										nodes:[											&#123;category:0, name: &#x27;乔布斯&#x27;, value : 10, label: &#x27;乔布斯\n（主要）&#x27;&#125;,											&#123;category:1, name: &#x27;丽萨-乔布斯&#x27;,value : 2&#125;,											&#123;category:1, name: &#x27;保罗-乔布斯&#x27;,value : 3&#125;,											&#123;category:1, name: &#x27;克拉拉-乔布斯&#x27;,value : 3&#125;,											&#123;category:1, name: &#x27;劳伦-鲍威尔&#x27;,value : 7&#125;,											&#123;category:2, name: &#x27;史蒂夫-沃兹尼艾克&#x27;,value : 5&#125;,											&#123;category:2, name: &#x27;奥巴马&#x27;,value : 8&#125;,											&#123;category:2, name: &#x27;比尔-盖茨&#x27;,value : 9&#125;,											&#123;category:2, name: &#x27;乔纳森-艾夫&#x27;,value : 4&#125;,											&#123;category:2, name: &#x27;蒂姆-库克&#x27;,value : 4&#125;,											&#123;category:2, name: &#x27;龙-韦恩&#x27;,value : 1&#125;,										],										links : [											&#123;source : &#x27;丽萨-乔布斯&#x27;, target : &#x27;乔布斯&#x27;, weight : 1, name: &#x27;女儿&#x27;&#125;,											&#123;source : &#x27;保罗-乔布斯&#x27;, target : &#x27;乔布斯&#x27;, weight : 2, name: &#x27;父亲&#x27;&#125;,											&#123;source : &#x27;克拉拉-乔布斯&#x27;, target : &#x27;乔布斯&#x27;, weight : 1, name: &#x27;母亲&#x27;&#125;,											&#123;source : &#x27;劳伦-鲍威尔&#x27;, target : &#x27;乔布斯&#x27;, weight : 2&#125;,											&#123;source : &#x27;史蒂夫-沃兹尼艾克&#x27;, target : &#x27;乔布斯&#x27;, weight : 3, name: &#x27;合伙人&#x27;&#125;,											&#123;source : &#x27;奥巴马&#x27;, target : &#x27;乔布斯&#x27;, weight : 1&#125;,											&#123;source : &#x27;比尔-盖茨&#x27;, target : &#x27;乔布斯&#x27;, weight : 6, name: &#x27;竞争对手&#x27;&#125;,											&#123;source : &#x27;乔纳森-艾夫&#x27;, target : &#x27;乔布斯&#x27;, weight : 1, name: &#x27;爱将&#x27;&#125;,											&#123;source : &#x27;蒂姆-库克&#x27;, target : &#x27;乔布斯&#x27;, weight : 1&#125;,											&#123;source : &#x27;龙-韦恩&#x27;, target : &#x27;乔布斯&#x27;, weight : 1&#125;,											&#123;source : &#x27;克拉拉-乔布斯&#x27;, target : &#x27;保罗-乔布斯&#x27;, weight : 1&#125;,											&#123;source : &#x27;奥巴马&#x27;, target : &#x27;保罗-乔布斯&#x27;, weight : 1&#125;,											&#123;source : &#x27;奥巴马&#x27;, target : &#x27;克拉拉-乔布斯&#x27;, weight : 1&#125;,											&#123;source : &#x27;奥巴马&#x27;, target : &#x27;劳伦-鲍威尔&#x27;, weight : 1&#125;,											&#123;source : &#x27;奥巴马&#x27;, target : &#x27;史蒂夫-沃兹尼艾克&#x27;, weight : 1&#125;,											&#123;source : &#x27;比尔-盖茨&#x27;, target : &#x27;奥巴马&#x27;, weight : 6&#125;,											&#123;source : &#x27;比尔-盖茨&#x27;, target : &#x27;克拉拉-乔布斯&#x27;, weight : 1&#125;,											&#123;source : &#x27;蒂姆-库克&#x27;, target : &#x27;奥巴马&#x27;, weight : 1&#125;										]									&#125;								]								//此处以上是官网上调试好的数据代码								//------------------------------------------							&#125;								&lt;!--step4-2-2-2 初始化echarts，并且引入主题&#x27;chalk&#x27;--&gt;				var myChart2 = ec.init(document.getElementById(&#x27;main&#x27;),&#x27;chalk&#x27;); //,&#x27;macarons&#x27;主题				&lt;!--step4-2-2-3 为myChart设置数据--&gt;				myChart2.setOption(option);					&#125;		);		&lt;/script&gt;&lt;/html&gt;

【痴迷音乐】

方案一直接到音乐网站中生成外链播放器，就有自动生成如下标签，直接放进md文件中即可。
&lt;iframe frameborder=&quot;no&quot; border=&quot;0&quot; marginwidth=&quot;0&quot; marginheight=&quot;0&quot; width=0 height=0 src=&quot;http://streamoc.music.tc.qq.com/M800101A9o5D1EWzyd.mp3?vkey=496F425FDC1F092E0924D5ADD6BA7AA6837C8528BF0696B09AE2DC0FCB8B1CCDCFBFABB6C0EDC11B17B69138025492940BF54F6EA14B310A&amp;guid=MS&amp;fromtag=8&amp;uin=0&quot;&gt;&lt;/iframe&gt;


把width&#x3D;和height设置为0，在网页中看不见,但可以自动播放，有点像网页背景音乐。点击此处查看具体效果！ 
方案二【个人推荐】使用Hexo插件APlayer！！！
首先在 git bash中使用命令npm install hexo-tag-aplayer


使用leancloudlencloud可以完美解决图片与音乐外链问题。在leancloud官网注册后，可以选择个人用户开发版，这是免费的！然后在class中找到_File上传自己的音乐和图片，后面会有它的链接，直接copy就行。
在md文件中具体添加音乐【添加一首歌】
